package mx.digilizate.desktop;
import java.nio.file.*;import java.util.*;
public class Tests{static void check(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("OK: "+s);}public static void main(String[] args)throws Exception{Path p=Files.createTempDirectory("dgz-test").resolve("data.bin");Registry r=new Registry(p);r.put(null,new Registry.Worker("B","Ana","Zeta",true));r.put(null,new Registry.Worker("A","Luis","Alfa",true));check(r.find("a").name().equals("Luis"),"Registro y búsqueda binaria");try{r.put(null,new Registry.Worker("A","X","Y",true));throw new AssertionError();}catch(IllegalArgumentException e){check(true,"Duplicado rechazado");}r.put("A",new Registry.Worker("A","Pedro","Alfa",true));check(r.find("A").name().equals("Pedro"),"Edición");r.undo();check(r.find("A").name().equals("Luis"),"Pila deshacer");r.delete("B");check(r.find("B")==null,"Eliminación");r.attendance("A");try{r.delete("A");throw new AssertionError();}catch(IllegalArgumentException e){check(true,"Integridad de asistencias");}check(new Registry(p).events().size()==1,"Persistencia");var q=new DataEngine.Queue<Integer>();q.enqueue(1);q.enqueue(2);check(q.dequeue()==1&&q.dequeue()==2,"Cola FIFO");var a=new ArrayList<>(List.of(3,1,2,1));DataEngine.mergeSort(a,Comparator.naturalOrder());check(a.equals(List.of(1,1,2,3)),"Merge Sort");check(DataEngine.linearSearch(a,x->x==1).size()==2,"Búsqueda lineal");}}
